// 32-bit global branch history shift register, with prediction and
// feedback. The prediction stage can roll back the register state when a
// pipeline flush occurs (predict_valid=1, predict_taken=1).
module TopModule(
    input  clk,
    input  areset,
    input  predict_valid,
    input  predict_taken,
    input  train_mispredicted,
    input  train_taken,
    input  [31:0] train_history,
    output [31:0] predict_history
);
    reg [31:0] history;
    always @(posedge clk) begin
        if (areset) history <= 32'd0;
        else begin
            if (predict_valid) begin
                // Predict, possibly rolling back state
                if (predict_taken) history <= {history[30:0], 1'b1};
                else                 history <= {history[30:0], 1'b0};
            end else if (train_mispredicted) begin
                // Misprediction - load the history register with the
                // history after the completed branch
                history <= {train_history, train_taken};
            end else begin
                // No prediction or misprediction - just shift the history
                history <= {history[30:0], history[31]};
            end
        end
    end
    assign predict_history = history;
endmodule

